import React from 'react';import {createRoot} from 'react-dom/client';import {Splitter,Button,MtoneProvider} from '../../packages/mtone/src';import '../../packages/mtone/dist/styles.css';
function Demo(){const [orientation,setOrientation]=React.useState<'horizontal'|'vertical'>('horizontal');const [rtl,setRtl]=React.useState(false);const [controlled,setControlled]=React.useState(false);const [accept,setAccept]=React.useState(true);const [sizes,setSizes]=React.useState<number[]|undefined>();const [third,setThird]=React.useState(false);const [mounted,setMounted]=React.useState(true);const [narrow,setNarrow]=React.useState(false);const [disabled,setDisabled]=React.useState(false);const [padded,setPadded]=React.useState(false);const [nested,setNested]=React.useState(false);const [lazy,setLazy]=React.useState(false);React.useEffect(()=>{const key=(e:KeyboardEvent)=>{if(e.key==='u')setMounted(x=>!x)};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[]);const [starts,setStarts]=React.useState(0);const [ends,setEnds]=React.useState(0);const [latest,setLatest]=React.useState<number[]>([]);
return <MtoneProvider locale="en"><div style={{display:'flex',flexWrap:'wrap',gap:8}}><Button onClick={()=>setPadded(x=>!x)}>Padding</Button><Button onClick={()=>setNested(x=>!x)}>Nested</Button><Button onClick={()=>setLazy(x=>!x)}>Lazy</Button><Button onClick={()=>setOrientation(x=>x==='horizontal'?'vertical':'horizontal')}>Orientation</Button><Button onClick={()=>setRtl(x=>!x)}>RTL</Button><Button onClick={()=>{setControlled(x=>!x);setSizes(undefined);}}>Controlled</Button><Button onClick={()=>setAccept(x=>!x)}>Accept</Button><Button onClick={()=>setThird(x=>!x)}>Third</Button><Button onClick={()=>setMounted(x=>!x)}>Mount</Button><Button onClick={()=>setNarrow(x=>!x)}>Narrow</Button><Button onClick={()=>setDisabled(x=>!x)}>Disable</Button></div>
<output data-testid="events">{JSON.stringify({starts,ends,latest,controlled,accept})}</output>
<div style={{width:narrow?320:600,maxWidth:'100%',height:360,marginTop:20}}>{mounted&&<Splitter aria-label="Test workspace" orientation={orientation} lazy={lazy} dir={rtl?'rtl':'ltr'} disabled={disabled} sizes={controlled?(sizes??['40%','60%']):undefined} onResizeStart={()=>setStarts(x=>x+1)} onResizeEnd={()=>setEnds(x=>x+1)} onResize={next=>{setLatest(next);if(controlled&&accept)setSizes(next);}} style={{height:'100%',width:'100%',padding:padded?20:0,gap:padded?8:0}}><Splitter.Panel id="left" label="Left panel" defaultSize="40%" min="20%" max="70%" collapsible><div data-content="left"><strong>Left panel</strong><Button>Inside left</Button></div></Splitter.Panel><Splitter.Panel id="right" label="Right panel" min="20%"><div data-content="right">Right panel</div>{nested&&<Splitter aria-label="Nested workspace" orientation="vertical" style={{height:240}}><Splitter.Panel id="inner-a">Inner A</Splitter.Panel><Splitter.Panel id="inner-b">Inner B</Splitter.Panel></Splitter>}</Splitter.Panel>{third&&<Splitter.Panel id="third" label="Third panel" defaultSize="20%" min="10%"><div data-content="third">Third panel</div></Splitter.Panel>}</Splitter>}</div></MtoneProvider>;}createRoot(document.getElementById('root')!).render(<Demo/>);
